<?php
declare(strict_types=1);require_once __DIR__.'/config.php';function te($s){return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sendTelegramMessage($m){if(TELEGRAM_BOT_TOKEN==='TOKEN_TELEGRAM_AICI'||TELEGRAM_CHAT_ID==='CHAT_ID_AICI')throw new RuntimeException('Telegram nu este configurat.');$ch=curl_init('https://api.telegram.org/bot'.TELEGRAM_BOT_TOKEN.'/sendMessage');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>REQUEST_TIMEOUT,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['chat_id'=>TELEGRAM_CHAT_ID,'text'=>$m,'parse_mode'=>'HTML','disable_web_page_preview'=>true],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$r=json_decode(curl_exec($ch),true);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!is_array($r)||$code<200||$code>=300||empty($r['ok']))throw new RuntimeException('Telegram: '.($r['description']??'eroare'));return $r;}function buildTelegramOfferMessage($c,$ps,$total,$no,$url=''){ $m="🟢 <b>OFERTĂ NOUĂ – OFFICEPLUS</b>\n━━━━━━━━━━━━━━\n📄 <b>Oferta:</b> ".te($no)."\n\n👤 <b>CLIENT</b>\n";foreach(['name'=>'Nume','phone'=>'📞 Telefon','email'=>'✉️ Email','company'=>'🏢 Companie','city'=>'📍 Localitate','address'=>'🏠 Adresă'] as $k=>$l)if(!empty($c[$k]))$m.=$l.': '.te($c[$k])."\n";$m.="\n🛒 <b>PRODUSE</b>\n";$n=1;foreach($ps as $p){$q=(int)$p['quantity'];$pr=(float)$p['price'];$m.=$n.'. <b>'.te($p['name']??'Produs')."</b>\nCant.: $q × ".number_format($pr,2,'.',' ').' MDL = <b>'.number_format($q*$pr,2,'.',' ')." MDL</b>\n";$n++;}$m.="\n💰 <b>TOTAL: ".number_format($total,2,'.',' ').' MDL</b>\n';if($url)$m.='📄 <a href="'.te($url).'">Deschide oferta PDF</a>\n';return $m.'\nOfficePlus – Partenerul tău pentru productivitate';}
